m['deliveryNotes']=['Photo-based reconstruction, not a measured as-built survey.','Only visible public counter and ingredient bay are detailed. Unseen kitchen remains simplified.','GLB is self-contained; no external texture/network dependencies.','Master includes hidden EXPORT collection and fully editable LOW source geometry/text.','Canopy toggle uses canopy_ prefix.','No rig, animation, physics or collision provided.']
m['revisionHistory']=[{'version':'1.2','reason':'User identified incorrect thin, forward-projecting red partition beside the counter.','evidence':['review/partition-2.3.jpg','review/partition-2.8.jpg','review/partition-3.3.jpg','review/partition-evidence.jpg'],'observed':'Broad red front face meets the tiled service backwall; entrance turns to the right of this mass. Six notices occupy two rows of three on the red face.','previous_m':{'x':[2.77,3.05],'y':[.065,2.975],'width':.28},'correctedInferred_m':{'x':[2.05,3.05],'frontY':1.20,'rearY':2.99,'width':1.0},'changes':['Red mass moved back to approximately the service wall plane, widened toward the left, and given a recess for the existing left ingredient case.','Tiled service wall now ends at x=2.05 without overlapping the red face.','Six notice panels enlarged and positioned on the corrected front face.'],'preserved':['Counter position and dimensions','All three ingredient refrigerator placements','Right edge of the entrance-left red mass at x=3.05','Other fixture, food and flower placement choices'],'uncertainty':'1.0 m width and 1.20 m setback are perspective-based estimates, not surveyed measurements. Close comparison is from a similar but uncalibrated camera.'}]
m['inferred'].append('Current red mass front end spans x=2.05..3.35 m, y=1.20..1.44 m; 1.30 m width and 0.24 m end depth remain inferred. Its full face covers the left refrigerator end, following explicit user correction.')
clear=json.loads((root/'review/clearance-validation.json').read_text())
m['validation']['clearance']=clear
