m['cameraMatch']={'source':'QT frames near 2.8 and 3.8 seconds','lens_mm':24,'sensorFit':'VERTICAL','sensorHeight_mm':36,'qualification':'Approximate phone field of view and eye-level camera; no measured camera calibration.','partitionCameraBlender':{'position':[3.4,-.7,1.65],'target':[2.85,1.45,1.40]},'aisleCameraBlender':{'position':[3.85,-.6,1.65],'target':[3.85,2.95,1.40]}}
