m['buildSteps'] += ['blender --background --python build/04_entry_review.py','python build/05_review_annotation.py','python build/03_finalize_manifest.py']
m['inferred']=list(dict.fromkeys(m['inferred']))
m['revisionHistory'].append({'version':'1.5','reason':'User corrected the canopy junction and requested the right end wall be at least 0.60 m wide and fully conceal the bowl station side.','changes':['Shortened the existing entry arch depth to 0.68 m and gave the hanging end an ivory underside.','Extended the main luminous canopy rear end by 0.40 m.','Rebuilt the entry soffit to rise into the rear flat ceiling; the right curve meets the widened wall end.','Replaced the isolated niche header with a continuous red side wall and brown side-wall tile reveal above.','Replaced the thin 0.26 m outer pier with a 0.845 m tiled full end return, covering the entire bowl-warmer side from the front.'],'rightEndReturn':clear.get('rightCaseEndReturn'),'clearance_m':clear['continuousStraightCorridor_m'],'qualification':'The 0.60 m minimum and approximately 1 m aisle are user estimates; other geometry remains inferred from uncalibrated images. Counter and terminal projection differences remain outside this localized revision.'})
m['validation']['visualReview']['views']+=['canopy-v1.5-detail.png','canopy-v1.5-front.png','canopy-v1.5-entrance.png']
m['validation']['visualReview']['checked']+=['Same original-photo crop used to inspect the canopy junction','Right wall front width and full warmer-side coverage verified from evaluated mesh bounds','Right wall checked in front elevation and oblique entry views; clear aisle remains at least 1 m']
m['buildSteps']+=['For v1.5 revision: apply build/canopy_detail_geometry.py to preserved review/UBowl_v1.4_before_canopy.blend, save master, then run 02_export_review.py, validate.py, and 03_finalize_manifest.py.']
(root/'asset-manifest.json').write_text(json.dumps(m,ensure_ascii=False,indent=2),encoding='utf8')
print(json.dumps({'bytes':m['glbBytes'],'sha256':m['glbSHA256'],'mesh':m['meshObjects'],'triangles':m['meshTriangles'],'drawCalls':m['drawCallsWithoutShadows'],'runtimeVertices':m['exportRuntimeVertices'],'roundtrip':rt['status'],'topologyFail':len(t['summary']['fail'])}))
